-- Reference schema 2. Onboarding creates these tables automatically. Do not import before setup.
CREATE TABLE meta (name VARCHAR(100) PRIMARY KEY, value LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(150) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE tokens (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, hash VARCHAR(64) NOT NULL UNIQUE, label VARCHAR(150) NOT NULL, expires VARCHAR(30) NOT NULL, revoked INTEGER NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE records (id BIGINT PRIMARY KEY AUTO_INCREMENT, kind VARCHAR(40) NOT NULL, payload LONGTEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created VARCHAR(30) NOT NULL, updated VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE revisions (id BIGINT PRIMARY KEY AUTO_INCREMENT, record_id BIGINT NOT NULL, user_id BIGINT NOT NULL, payload LONGTEXT NOT NULL, action VARCHAR(40) NOT NULL, created VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE requests (request_key VARCHAR(100) PRIMARY KEY, user_id BIGINT NOT NULL, response LONGTEXT NOT NULL, created VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE files (id BIGINT PRIMARY KEY AUTO_INCREMENT, record_id BIGINT NOT NULL, user_id BIGINT NOT NULL, filename VARCHAR(100) NOT NULL, mime VARCHAR(40) NOT NULL, caption LONGTEXT NOT NULL, view_label VARCHAR(40) NOT NULL, item_key VARCHAR(80), created VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO meta(name,value) VALUES ('schema_version','2') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
